// Shared "pick a model/variant/colour, auto-fill the price fields" widget
// for the Quote and Booking forms. Reads public/data/priceCatalog.json
// (Toyota's official price-list PDFs) and public/data/suffixColorCodes.json
// (the model suffix/colour reference sheet) — both generated by the
// scripts/parse_*.py scripts. Values are a starting point — every field it
// fills stays a normal editable input.

// A few of the two data sources' model names don't match by substring
// (different abbreviations/spellings between the price lists and the
// suffix/colour sheet), so route those explicitly.
const MODEL_NAME_ALIASES = {
  LC: 'LAND CRUISER 300',
  HILUX: 'HILLUX',
};

export async function initPriceCatalog({ modelSelectId, variantSelectId, colorSelectId, fieldMap, hintId }) {
  const modelSelect = document.getElementById(modelSelectId);
  const variantSelect = document.getElementById(variantSelectId);
  const colorSelect = colorSelectId ? document.getElementById(colorSelectId) : null;
  if (!modelSelect || !variantSelect) return;

  const [priceRows, colorSections] = await Promise.all([
    fetchJson('/data/priceCatalog.json').then(d => d?.rows || []),
    fetchJson('/data/suffixColorCodes.json').then(d => d?.sections || []),
  ]);

  if (!priceRows.length) return;

  const vehicles = [...new Set(priceRows.map(r => r.vehicle))].sort();
  modelSelect.innerHTML = '<option value="">Select model to auto-fill prices…</option>' +
    vehicles.map(v => `<option value="${escapeHtml(v)}">${escapeHtml(v)}</option>`).join('');

  function populateVariants(vehicle) {
    const matches = priceRows.filter(r => r.vehicle === vehicle);
    variantSelect.disabled = matches.length === 0;
    variantSelect.innerHTML = '<option value="">Select variant…</option>' +
      matches.map((r, i) => {
        const label = [r.variant, r.suffixCode].filter(Boolean).join(' — ') +
          (r.exShowroomPrice ? ` (₹${r.exShowroomPrice.toLocaleString('en-IN')})` : '');
        return `<option value="${i}">${escapeHtml(label)}</option>`;
      }).join('');
    variantSelect.dataset.vehicle = vehicle;
  }

  function populateColors(vehicle) {
    if (!colorSelect) return;
    const section = findColorSection(colorSections, vehicle);
    const options = section ? section.variants.filter(v => v.colour) : [];
    colorSelect.disabled = options.length === 0;
    colorSelect.innerHTML = options.length
      ? '<option value="">Select colour…</option>' + options.map((v, i) => {
          const label = [v.colour, v.model, v.newSuffix || v.oldSuffix].filter(Boolean).join(' — ');
          return `<option value="${i}">${escapeHtml(label)}</option>`;
        }).join('')
      : '<option value="">No colour data for this model</option>';
    colorSelect.dataset.vehicle = vehicle;
    colorSelect.dataset.sectionModel = section ? section.modelName : '';
  }

  modelSelect.addEventListener('change', () => {
    populateVariants(modelSelect.value);
    populateColors(modelSelect.value);
  });

  variantSelect.addEventListener('change', () => {
    if (variantSelect.value === '') return;
    const matches = priceRows.filter(r => r.vehicle === variantSelect.dataset.vehicle);
    const row = matches[Number(variantSelect.value)];
    if (!row) return;
    applyPriceRow(row, fieldMap);
    setHint(hintId, `Filled from ${row.sourceFile} — review before saving.`);
  });

  if (colorSelect) {
    colorSelect.addEventListener('change', () => {
      if (colorSelect.value === '') return;
      const section = colorSections.find(s => s.modelName === colorSelect.dataset.sectionModel);
      const entry = section && section.variants[Number(colorSelect.value)];
      if (!entry) return;
      setField(fieldMap.color, entry.colour);
      if (!getField(fieldMap.suffix)?.value) {
        setField(fieldMap.suffix, entry.newSuffix || entry.oldSuffix || '');
      }
      setHint(hintId, `Colour filled from the suffix/colour code sheet (${section.modelName}) — review before saving.`);
    });
  }
}

// Words too generic to count as a "this is the same model" signal on their
// own (trim/powertrain descriptors, boilerplate) — stripped before scoring
// token overlap between a price-list vehicle name and a colour-sheet
// section name, since the two sources abbreviate/order words differently
// (e.g. "URBAN CRUISER TAISOR" vs "UC TAISOR").
const STOPWORDS = new Set([
  'URBAN', 'CRUISER', 'NEW', 'PRIVATE', 'COMMERCIAL', 'HYBRID', 'PETROL', 'DIESEL',
  'CNG', 'WHITE', 'PEARL', 'HIGH', 'GRADE', 'NEO', 'DRIVE', 'DUAL', 'TONE', 'EDITION',
]);

function significantTokens(s) {
  return normalize(s)
    .split(/[^A-Z0-9]+/)
    .filter(t => t.length >= 2 && !STOPWORDS.has(t));
}

function findColorSection(sections, vehicle) {
  const aliased = MODEL_NAME_ALIASES[vehicle.toUpperCase()];
  if (aliased) {
    const exact = sections.find(s => normalize(s.modelName) === normalize(aliased));
    if (exact) return exact;
  }

  const targetTokens = new Set(significantTokens(vehicle));
  let best = null;
  let bestScore = 0;
  for (const s of sections) {
    const sectionTokens = significantTokens(s.modelName);
    const score = sectionTokens.filter(t => targetTokens.has(t)).length;
    if (score > bestScore) {
      best = s;
      bestScore = score;
    }
  }
  return bestScore > 0 ? best : null;
}

function normalize(s) {
  return String(s || '').toUpperCase().trim();
}

async function fetchJson(url) {
  try {
    const res = await fetch(url);
    return await res.json();
  } catch (err) {
    console.error('Could not load', url, err);
    return null;
  }
}

function getField(name) {
  return name ? document.querySelector(`[name="${name}"]`) : null;
}

function setField(name, value) {
  const el = getField(name);
  if (el && value !== undefined && value !== null) el.value = value;
}

function setHint(hintId, text) {
  if (!hintId) return;
  const hint = document.getElementById(hintId);
  if (hint) hint.textContent = text;
}

function applyPriceRow(row, fieldMap) {
  setField(fieldMap.model, row.vehicle);
  setField(fieldMap.suffix, row.suffixCode || '');
  setField(fieldMap.vehicleCost, row.exShowroomPrice);
  setField(fieldMap.registrationRoadTax, row.roadTaxRegistration);
  setField(fieldMap.extendedWarranty, row.trueWarranty);

  const insuranceValues = Object.values(row.insurance || {});
  if (insuranceValues.length) setField(fieldMap.toyotaProtect, insuranceValues[0]);

  const coating = (row.smilePackage || 0) + (row.tgloss || 0);
  if (coating) setField(fieldMap.smilesCoating, coating);

  if (row.tga) setField(fieldMap.tga, row.tga);
}

function escapeHtml(s) {
  return String(s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
}
